// h264/ring_words_in.sv -- the HPS interface's input region, words 48-71 (0.6; generated by tools/ring_layout.py -- edit the tables there, never this file).
// A mux on the region's own word index (0 = word 48): combinational; h264/ring_in.sv holds
// the state it reads still while h264/ring_stat.sv pushes the region's words.

`default_nettype none

module ring_words_in (
    input  wire  [4:0]  ix,
    input  wire  [31:0] f_in_head,           // w48: (0.6) +1 each write of the region; read LAST
    input  wire  [31:0] f_ev_count,          // w48: (0.6) events queued since the PLL lock (free-running): the next event's number
    input  wire  [31:0] f_pad0_joy,          // w49: (0.6) pad 0: hps_io's joystick_0 (the d-pad [3:0], the J line's buttons from [4])
    input  wire  [15:0] f_pad0_lstick,       // w49: (0.6) ... its left stick: Y [15:8], X [7:0], signed -127..127
    input  wire  [15:0] f_pad0_rstick,       // w49: (0.6) ... its right stick
    input  wire  [31:0] f_pad1_joy,          // w50: (0.6) pad 1: hps_io's joystick_1 (the d-pad [3:0], the J line's buttons from [4])
    input  wire  [15:0] f_pad1_lstick,       // w50: (0.6) ... left stick
    input  wire  [15:0] f_pad1_rstick,       // w50: (0.6) ... right stick
    input  wire  [31:0] f_pad2_joy,          // w51: (0.6) pad 2: hps_io's joystick_2 (the d-pad [3:0], the J line's buttons from [4])
    input  wire  [15:0] f_pad2_lstick,       // w51: (0.6) ... left stick
    input  wire  [15:0] f_pad2_rstick,       // w51: (0.6) ... right stick
    input  wire  [31:0] f_pad3_joy,          // w52: (0.6) pad 3: hps_io's joystick_3 (the d-pad [3:0], the J line's buttons from [4])
    input  wire  [15:0] f_pad3_lstick,       // w52: (0.6) ... left stick
    input  wire  [15:0] f_pad3_rstick,       // w52: (0.6) ... right stick
    input  wire  [31:0] f_pad4_joy,          // w53: (0.6) pad 4: hps_io's joystick_4 (the d-pad [3:0], the J line's buttons from [4])
    input  wire  [15:0] f_pad4_lstick,       // w53: (0.6) ... left stick
    input  wire  [15:0] f_pad4_rstick,       // w53: (0.6) ... right stick
    input  wire  [31:0] f_pad5_joy,          // w54: (0.6) pad 5: hps_io's joystick_5 (the d-pad [3:0], the J line's buttons from [4])
    input  wire  [15:0] f_pad5_lstick,       // w54: (0.6) ... left stick
    input  wire  [15:0] f_pad5_rstick,       // w54: (0.6) ... right stick
    input  wire  [31:0] f_dx_sum,            // w55: (0.6) the mouse: the sum of every packet's dx (signed, wrapping)
    input  wire  [31:0] f_dy_sum,            // w55: (0.6) ... of every packet's dy (Y up-positive, as PS/2 packs it)
    input  wire  [15:0] f_ev_q0,             // w56: (0.6) event queue entry 0
    input  wire  [15:0] f_ev_q1,             // w56: (0.6) event queue entry 1
    input  wire  [15:0] f_ev_q2,             // w56: (0.6) event queue entry 2
    input  wire  [15:0] f_ev_q3,             // w56: (0.6) event queue entry 3
    input  wire  [15:0] f_ev_q4,             // w57: (0.6) event queue entry 4
    input  wire  [15:0] f_ev_q5,             // w57: (0.6) event queue entry 5
    input  wire  [15:0] f_ev_q6,             // w57: (0.6) event queue entry 6
    input  wire  [15:0] f_ev_q7,             // w57: (0.6) event queue entry 7
    input  wire  [15:0] f_ev_q8,             // w58: (0.6) event queue entry 8
    input  wire  [15:0] f_ev_q9,             // w58: (0.6) event queue entry 9
    input  wire  [15:0] f_ev_q10,            // w58: (0.6) event queue entry 10
    input  wire  [15:0] f_ev_q11,            // w58: (0.6) event queue entry 11
    input  wire  [15:0] f_ev_q12,            // w59: (0.6) event queue entry 12
    input  wire  [15:0] f_ev_q13,            // w59: (0.6) event queue entry 13
    input  wire  [15:0] f_ev_q14,            // w59: (0.6) event queue entry 14
    input  wire  [15:0] f_ev_q15,            // w59: (0.6) event queue entry 15
    input  wire  [15:0] f_ev_q16,            // w60: (0.6) event queue entry 16
    input  wire  [15:0] f_ev_q17,            // w60: (0.6) event queue entry 17
    input  wire  [15:0] f_ev_q18,            // w60: (0.6) event queue entry 18
    input  wire  [15:0] f_ev_q19,            // w60: (0.6) event queue entry 19
    input  wire  [15:0] f_ev_q20,            // w61: (0.6) event queue entry 20
    input  wire  [15:0] f_ev_q21,            // w61: (0.6) event queue entry 21
    input  wire  [15:0] f_ev_q22,            // w61: (0.6) event queue entry 22
    input  wire  [15:0] f_ev_q23,            // w61: (0.6) event queue entry 23
    input  wire  [15:0] f_ev_q24,            // w62: (0.6) event queue entry 24
    input  wire  [15:0] f_ev_q25,            // w62: (0.6) event queue entry 25
    input  wire  [15:0] f_ev_q26,            // w62: (0.6) event queue entry 26
    input  wire  [15:0] f_ev_q27,            // w62: (0.6) event queue entry 27
    input  wire  [15:0] f_ev_q28,            // w63: (0.6) event queue entry 28
    input  wire  [15:0] f_ev_q29,            // w63: (0.6) event queue entry 29
    input  wire  [15:0] f_ev_q30,            // w63: (0.6) event queue entry 30
    input  wire  [15:0] f_ev_q31,            // w63: (0.6) event queue entry 31
    input  wire  [31:0] f_wheel_sum,         // w64: (0.6) the sum of every packet's wheel (signed, wrapping)
    input  wire  [7:0] f_mouse_btn,         // w64: (0.6) the mouse buttons now: [0] L [1] R [2] M [7:3] buttons 4-8
    input  wire  [0:0] f_osd_open,          // w64: (0.6) Main's OSD is open (as last applied to the queue)
    input  wire  [15:0] f_ev_lost,           // w64: (0.6) events the core could not queue (a second from one source while the first waited; saturating)
    input  wire  [31:0] f_in_tail,           // w71: (0.6) in_head again: read FIRST (equal to in_head = a consistent copy)
    output logic [63:0] w
);
    always_comb begin
        w = 64'd0;
        case (ix)
            5'd0: begin w[31:0] = f_in_head; w[63:32] = f_ev_count; end
            5'd1: begin w[31:0] = f_pad0_joy; w[47:32] = f_pad0_lstick; w[63:48] = f_pad0_rstick; end
            5'd2: begin w[31:0] = f_pad1_joy; w[47:32] = f_pad1_lstick; w[63:48] = f_pad1_rstick; end
            5'd3: begin w[31:0] = f_pad2_joy; w[47:32] = f_pad2_lstick; w[63:48] = f_pad2_rstick; end
            5'd4: begin w[31:0] = f_pad3_joy; w[47:32] = f_pad3_lstick; w[63:48] = f_pad3_rstick; end
            5'd5: begin w[31:0] = f_pad4_joy; w[47:32] = f_pad4_lstick; w[63:48] = f_pad4_rstick; end
            5'd6: begin w[31:0] = f_pad5_joy; w[47:32] = f_pad5_lstick; w[63:48] = f_pad5_rstick; end
            5'd7: begin w[31:0] = f_dx_sum; w[63:32] = f_dy_sum; end
            5'd8: begin w[15:0] = f_ev_q0; w[31:16] = f_ev_q1; w[47:32] = f_ev_q2; w[63:48] = f_ev_q3; end
            5'd9: begin w[15:0] = f_ev_q4; w[31:16] = f_ev_q5; w[47:32] = f_ev_q6; w[63:48] = f_ev_q7; end
            5'd10: begin w[15:0] = f_ev_q8; w[31:16] = f_ev_q9; w[47:32] = f_ev_q10; w[63:48] = f_ev_q11; end
            5'd11: begin w[15:0] = f_ev_q12; w[31:16] = f_ev_q13; w[47:32] = f_ev_q14; w[63:48] = f_ev_q15; end
            5'd12: begin w[15:0] = f_ev_q16; w[31:16] = f_ev_q17; w[47:32] = f_ev_q18; w[63:48] = f_ev_q19; end
            5'd13: begin w[15:0] = f_ev_q20; w[31:16] = f_ev_q21; w[47:32] = f_ev_q22; w[63:48] = f_ev_q23; end
            5'd14: begin w[15:0] = f_ev_q24; w[31:16] = f_ev_q25; w[47:32] = f_ev_q26; w[63:48] = f_ev_q27; end
            5'd15: begin w[15:0] = f_ev_q28; w[31:16] = f_ev_q29; w[47:32] = f_ev_q30; w[63:48] = f_ev_q31; end
            5'd16: begin w[31:0] = f_wheel_sum; w[39:32] = f_mouse_btn; w[40:40] = f_osd_open; w[63:48] = f_ev_lost; end
            5'd23: begin w[31:0] = f_in_tail; end
            default: ;
        endcase
    end
endmodule

`default_nettype wire
